const raw = $input.first().json.input;
const inp = typeof raw === 'string' ? JSON.parse(raw) : (raw || $input.first().json);
const uid = (inp.firebaseUid || '').trim();
if (!/^[A-Za-z0-9]{20,64}$/.test(uid)) {
  throw new Error('firebaseUid inválido: ' + uid);
}
return [{ json: { firebaseUid: uid } }];

const catRows = $('Top Categorías').all();
const bookRows = $('Últimos Libros').all();

const topCategories = catRows
  .map(r => r.json)
  .filter(j => j && !j.error && j.category)
  .map(j => ({ category: j.category, freq: Number(j.freq) }));

const recentBooks = bookRows
  .map(r => r.json)
  .filter(j => j && !j.error && j.id)
  .map(j => ({ id: Number(j.id), title: j.title || '', author: j.author || '' }));

return [{ json: { topCategories, recentBooks } }];
